{"signature":"public.review_assessed_submission_details(uuid,text,text,jsonb,uuid,jsonb)","name":"review_assessed_submission_details","arg_types":["uuid","text","text","jsonb","uuid","jsonb"],"migration":"202611070003_assessment_transparency.sql","body_md5":"b86dda6c2733d35879135237fdf7d34b","history":[{"migration":"202611070003_assessment_transparency.sql","body_md5":"b86dda6c2733d35879135237fdf7d34b"}]}]$function_reference$::jsonb j),
expected as (select x.* from reference,jsonb_to_recordset(j) x(signature text,name text,arg_types jsonb,migration text,body_md5 text,history jsonb)),
compared as (
 select e.*,p.oid,p.prosecdef,p.proconfig,
 md5(p.prosrc) as raw_body_md5,
 md5(replace(p.prosrc,chr(13)||chr(10),chr(10))) as lf_body_md5
 from expected e cross join lateral (
  select coalesce(bool_and(to_regtype(v) is not null),true) as types_present,
   coalesce(string_agg(to_regtype(v)::oid::text,' ' order by i),'') as args
  from jsonb_array_elements_text(e.arg_types) with ordinality t(v,i)
 ) a
 left join pg_catalog.pg_namespace n on n.nspname='public'
 left join pg_catalog.pg_proc p on p.pronamespace=n.oid and p.proname=e.name and a.types_present and p.proargtypes::text=a.args
)
select signature,oid is not null as function_exists,migration as latest_source,
 case when oid is null then 'MISSING'
 when lf_body_md5=body_md5 then 'LATEST_BODY_MATCH'
 when exists(select 1 from jsonb_array_elements(history) h where h->>'body_md5'=lf_body_md5) then 'KNOWN_OLDER_BODY'
 else 'UNEXPLAINED_BODY_DIFFERENCE' end as comparison,
 raw_body_md5,lf_body_md5,body_md5 as expected_latest_body_md5,
 coalesce((select jsonb_agg(h->>'migration') from jsonb_array_elements(history) h where h->>'body_md5'=lf_body_md5),'[]'::jsonb) as matching_source_versions,
 prosecdef as security_definer,proconfig as function_settings
from compared order by signature;
